using UnityEngine;
using UnityEditor;
using System.IO;

// Set 9-slice borders (25% each side) on all Tiling Grass textures
var folder = "Assets/Flynn/Sprites/Environment/Tiling Grass";
var guids = AssetDatabase.FindAssets("t:Texture2D", new[] { folder });
int processed = 0;

foreach (var guid in guids)
{
    var path = AssetDatabase.GUIDToAssetPath(guid);
    var importer = AssetImporter.GetAtPath(path) as TextureImporter;
    if (importer == null || importer.textureType != TextureImporterType.Sprite)
    {
        Debug.LogWarning($"Skipping {path} - not a sprite texture");
        continue;
    }

    // Get texture dimensions
    importer.GetSourceTextureWidthAndHeight(out int width, out int height);

    // Calculate 25% borders
    int borderX = Mathf.RoundToInt(width * 0.25f);
    int borderY = Mathf.RoundToInt(height * 0.25f);

    // Set sprite borders (left, bottom, right, top)
    importer.spriteBorder = new Vector4(borderX, borderY, borderX, borderY);

    // Ensure sprite mode is Single
    importer.spriteMode = (int)SpriteImportMode.Single;

    // Save and reimport
    importer.SaveAndReimport();
    processed++;

    Debug.Log($"Set borders ({borderX},{borderY},{borderX},{borderY}) on {Path.GetFileName(path)} ({width}x{height})");
}

Debug.Log($"Done! Processed {processed} textures with 9-slice borders.");

