    importer.SaveAndReimport();
    processed++;

    Debug.Log($"Set borders ({borderX},{borderY},{borderX},{borderY}) on {Path.GetFileName(path)} ({width}x{height})");
}

Debug.Log($"Done! Processed {processed} textures with 9-slice borders.");

using UnityEngine;
using UnityEditor;

var profilePath = "Assets/Flynn/SpriteShape/Grass.asset";
var profile = AssetDatabase.LoadAssetAtPath<UnityEngine.U2D.SpriteShape>(profilePath);
if (profile == null)
{
    Debug.LogError($"Could not load SpriteShape at {profilePath}");
    return;
}

var so = new SerializedObject(profile);

// Set m_UseSpriteBorders to true
var useBordersProp = so.FindProperty("m_UseSpriteBorders");
if (useBordersProp != null)
{
    Debug.Log($"UseSpriteBorders was: {useBordersProp.boolValue}");
    useBordersProp.boolValue = true;
    so.ApplyModifiedProperties();
    EditorUtility.SetDirty(profile);
    AssetDatabase.SaveAssets();
    Debug.Log("Set UseSpriteBorders = true on Grass.asset");
}
else
{
    Debug.LogWarning("Could not find m_UseSpriteBorders property");
}

// Log current state
so.Update();
var anglesProp = so.FindProperty("m_Angles");
if (anglesProp != null && anglesProp.arraySize > 0)
{
    var firstAngle = anglesProp.GetArrayElementAtIndex(0);
    var spritesProp = firstAngle.FindPropertyRelative("m_Sprites");
    if (spritesProp != null && spritesProp.arraySize > 0)
    {
        var spriteRef = spritesProp.GetArrayElementAtIndex(0);
        Debug.Log($"Angle range sprite: {spriteRef.objectReferenceValue?.name ?? "null"}");
    }
}

var fillProp = so.FindProperty("m_FillTexture");
if (fillProp != null)
{
    Debug.Log($"Fill texture: {fillProp.objectReferenceValue?.name ?? "null"}");
}

Debug.Log("Grass Sprite Shape profile updated.");

