args.script:
using UnityEngine;
using UnityEditor;
using UnityEngine.U2D;

// Load the Grass Sprite Shape profile
var profile = AssetDatabase.LoadAssetAtPath<SpriteShape>("Assets/Flynn/SpriteShape/Grass.asset");
if (profile == null)
{
    Debug.LogError("Could not load Grass Sprite Shape profile");
    return;
}

// Load the 01_grass_clean_center sprite for the fill
var cleanCenter = AssetDatabase.LoadAssetAtPath<Sprite>("Assets/Flynn/Sprites/Environment/Tiling Grass/01_grass_clean_center.png");

// Create the SpriteShape GameObject
var go = new GameObject("GrassTestSquare");
go.transform.position = new Vector3(0f, 0f, 0f);

var renderer = go.AddComponent<SpriteShapeRenderer>();
var controller = go.AddComponent<SpriteShapeController>();

// Assign the profile
controller.spriteShape = profile;

// Build a square: 4 control points forming a closed shape
// Spline is automatically created; we just need to set the points
var spline = controller.spline;
spline.Clear();

float half = 2f; // 4x4 unit square

// Bottom-left
spline.InsertPointAt(0, new Vector3(-half, -half, 0));
spline.SetTangentMode(0, ShapeTangentMode.Linear);

// Bottom-right
spline.InsertPointAt(1, new Vector3(half, -half, 0));
spline.SetTangentMode(1, ShapeTangentMode.Linear);

// Top-right
spline.InsertPointAt(2, new Vector3(half, half, 0));
spline.SetTangentMode(2, ShapeTangentMode.Linear);

// Top-left
spline.InsertPointAt(3, new Vector3(-half, half, 0));
spline.SetTangentMode(3, ShapeTangentMode.Linear);

// Close the shape (not open-ended)
controller.splineOpen = 0; // 0 = closed

// Refresh to bake the mesh
controller.RefreshSpriteShape();

Debug.Log($"Created GrassTestSquare at origin, 4x4 units, closed square with {spline.GetPointCount()} points");
Debug.Log($"Profile: {profile.name}, Open: {controller.splineOpen}");
if (cleanCenter != null)
    Debug.Log($"Clean center sprite loaded: {cleanCenter.name} ({cleanCenter.border})");

