using UnityEngine;
using UnityEditor;
using UnityEngine.U2D;

var profilePath = "Assets/Flynn/SpriteShape/Grass.asset";
var profile = AssetDatabase.LoadAssetAtPath<SpriteShape>(profilePath);

// Load the proper sprites
var cleanSprite = AssetDatabase.LoadAssetAtPath<Sprite>("Assets/Flynn/Sprites/Environment/Tiling Grass/01_grass_clean_center.png");
var cleanTex = AssetDatabase.LoadAssetAtPath<Texture2D>("Assets/Flynn/Sprites/Environment/Tiling Grass/01_grass_clean_center.png");

// Set the fill texture to the grass tile
var so = new SerializedObject(profile);

// Update fill texture
var fillProp = so.FindProperty("m_FillTexture");
if (fillProp != null)
{
    Debug.Log($"Fill was: {(fillProp.objectReferenceValue as Texture2D)?.name ?? "null"}");
    fillProp.objectReferenceValue = cleanTex;
    Debug.Log($"Fill set to: {cleanTex.name}");
}

// Update the edge sprite in the angle range
var anglesProp = so.FindProperty("m_Angles");
if (anglesProp != null && anglesProp.arraySize > 0)
{
    var firstAngle = anglesProp.GetArrayElementAtIndex(0);
    var spritesProp = firstAngle.FindPropertyRelative("m_Sprites");
    if (spritesProp != null && spritesProp.arraySize > 0)
    {
        var spriteRef = spritesProp.GetArrayElementAtIndex(0);
        Debug.Log($"Edge sprite was: {(spriteRef.objectReferenceValue as Sprite)?.name ?? "null"}");
        spriteRef.objectReferenceValue = cleanSprite;
        Debug.Log($"Edge sprite set to: {cleanSprite.name}");
    }
}

so.ApplyModifiedProperties();
EditorUtility.SetDirty(profile);
AssetDatabase.SaveAssets();

Debug.Log("Profile updated. Now refreshing the test square...");

// Now refresh the test square
var go = GameObject.Find("GrassTestSquare");
if (go != null)
{
    var controller = go.GetComponent<SpriteShapeController>();
    // Re-assign profile to force refresh
    controller.spriteShape = null;
    controller.spriteShape = profile;
    controller.RefreshSpriteShape();

    var mf = go.GetComponent<MeshFilter>();
    if (mf != null && mf.sharedMesh != null)
        Debug.Log($"Mesh: vertices={mf.sharedMesh.vertexCount}");
    else
        Debug.Log("Still no mesh - may need editor frame");
}

Debug.Log("Done!");

