using UnityEngine;
using UnityEngine.U2D;
using UnityEditor;

// Delete the stale bare one
var old = GameObject.Find("GrassTestSquare");
if (old != null) Object.DestroyImmediate(old);

// Step 1: Create with profile via delayed call to avoid timeout
EditorApplication.delayCall += () =>
{
    var profile = AssetDatabase.LoadAssetAtPath<SpriteShape>("Assets/Flynn/SpriteShape/Grass.asset");
    var go = new GameObject("GrassTestSquare");
    go.transform.position = Vector3.zero;
    var renderer = go.AddComponent<SpriteShapeRenderer>();
    var ctrl = go.AddComponent<SpriteShapeController>();
    ctrl.spriteShape = profile;

    // Set closed
    var so = new SerializedObject(ctrl);
    so.FindProperty("m_IsOpenEnded").boolValue = false;
    so.ApplyModifiedProperties();

    var spline = ctrl.spline;
    spline.Clear();
    float h = 2f;
    spline.InsertPointAt(0, new Vector3(-h, -h, 0)); spline.SetTangentMode(0, ShapeTangentMode.Linear);
    spline.InsertPointAt(1, new Vector3(h, -h, 0));  spline.SetTangentMode(1, ShapeTangentMode.Linear);
    spline.InsertPointAt(2, new Vector3(h, h, 0));    spline.SetTangentMode(2, ShapeTangentMode.Linear);
    spline.InsertPointAt(3, new Vector3(-h, h, 0));   spline.SetTangentMode(3, ShapeTangentMode.Linear);

    Selection.activeGameObject = go;
    Debug.Log("GrassTestSquare created and configured");
};

Debug.Log("Scheduled creation via delayCall");

